import { chromium } from "playwright-core";
const b = await chromium.launch({ executablePath: "/opt/google/chrome/chrome", args: ["--no-sandbox"] });
const ctx = await b.newContext({ viewport: { width: 412, height: 915 }, deviceScaleFactor: 2 });
await ctx.addInitScript(() => { localStorage.setItem("hermes.baseUrl", "https://homelab.tail0000.ts.net"); localStorage.setItem("hermes.apiKey", "x".repeat(32)); });
const p = await ctx.newPage(); const errs = []; p.on("pageerror", (e) => errs.push(String(e)));
await p.goto("http://localhost:8799/"); await p.waitForTimeout(3000);
await p.getByLabel("Open bots").filter({ visible: true }).first().click(); await p.waitForTimeout(600);
await p.getByText("New bot").filter({ visible: true }).first().click(); await p.waitForTimeout(1500);
await p.getByPlaceholder("jobwing").filter({ visible: true }).first().fill("JobWing");
await p.waitForTimeout(300);
await p.screenshot({ path: "/workspace/hermes-mobile/dist/screens/18-add-profile.png", fullPage: true });
console.log("button:", await p.getByText(/Check & add/).first().innerText(), "errors:", errs.length);
await b.close();
